/*OPPGAVE 1Husk å starte docker og riktig container! En god filstruktur kan skillemellom f.eks. C og B karaktermessig!OPPGAVE 22.1 - Finn tabelleneTabell      Kolonner        Representererareas       id, name        Èn avd. i dyresenteret (f.eks. CatWing)animals     id, name,       Ett bestemt dyr og hvilken avdeling det            species, weight er i nå            admittet_on            area_idAvdeling og dyr er to forskjellige "ting" med hver sine opplysninger,og forholdet er én til mange. Derfor blir det to tabeller. Siden vibare lagrer nåværende avdeling, trengs ingen tabell for historikk.2.2 - Velg datatyperFelt                Datatype        Påkrevd     Begrunnelseareas.name          varchar(40)     Ja + Unique Kort tekst med varierende lengde. Hver avd har unikt navnanimals.name        varchar(40)     Ja          Flere dyr kan hete det sammespecies             varchar(20)     Ja          Kort tekstweight              decimal(5, 2)   Nei(NULL)   Kg med to desimaler. Maks 999.99kgadmitted_on         date            Nei(NULL)   Dato u/tid.Ikke 0 kg på weight! NULL betyr at vi ikke har noen verdi. AVG(weight) hopper over NULL men tar med 0så her ville vi fått feil gjennomsnittsvekt.2.3 - Plasser nøkleneareas.id og animals.id er primærnøkler.area_id er en fremmednøkkel og hører til i animals, og peker på areas.id.! Som regel står fremmednøkkelen på many-siden i et 'one to many'-forhold.2.4 - Tegn forholdet(Bruker her < for kråkefottegnet)    [areas]-||--------------O<[animals]Tilhører nøyaktig 1         har 0..mange(min 1, max 1)*/-- OPPGAVE 3 - Opprett databasen og tabellene-- 3.1 - Create databasecreate database if not exists animal_shelter_practice;use animal_shelter_practice;select database(); -- sjekker at den finnes-- 3.2 Create table areascreate table if not exists areas (    id      int             primary key auto_increment,    name    varchar(40)     not null unique);-- 3.3 Create table animalsdrop table if exists animals;create table if not exists animals(    id          int             primary key auto_increment,    name        varchar(40)     not null,    species     varchar(20)     not null,    weight      decimal(5,2)    null,    admitted_on date            null,    area_id     int             not null,    foreign key (area_id)       references areas(id));/*3.4Filen leses og utføres fra toppen og ned. Dermed må avhengighetenekomme etter foreldretabellen. Så tabeller som ikke peker noen stederer foreldretabeller. Disse må stå øverst i dokumentet, eller i alle fallover de som peker til denne.Databasen sammenligner verdien i area_id med verdiene i areas.id. Typenemå være like (her er det int og int) for at det skal fungere. Vi kanf.eks. ikke ha varchar mot int. Da vil MySQL avvise fremmednøkkelen.*/-- OPPGAVE 4 - Legg inn og kontroller data-- 4.1 - Registrer avdelingene-- Først den ene avdelingeninsert into areas (name) values ('Cat Wing');-- så de 3 andre.insert into areas (name) values('Dog Wing'),('Small Animals'),('Quiet Zone');select id, name from areas order by id;-- Result in test run: 1 Cat Wing | 2 Dog Wing | 3 Small Animals | 4 Quiet Zone-- 4.2 - Registrer dyreneinsert into animals (name, species, weight, admitted_on, area_id) VALUES('Luna', 'cat', 3.80, '2026-09-12', 1),('Milo', 'cat', 4.20, null, 1),('Rex', 'dog', 18.50, '2026-09-15', 2),('Nala', 'dog', null, '2026-09-17', 2),('Pip', 'rabbit', 1.60, '2026-09-20', 3),('Luna', 'rabbit', 2.10, null, 3);-- 4.3 - Finn bestemte raderselect id, name, species, area_idfrom animalsorder by species, id;select id, name, species, weight, admitted_on, area_idfrom animalswhere name = 'Luna';select id, name, speciesfrom animalswhere id = 1;select id, name, admitted_onfrom animalswhere admitted_on is null;select id, name, weightfrom animalswhere weight is null;/*Et bestemt dyr identifiseres sikkert med priærnøkkelen (animals.id).I denne db fungerer det med navn, men hvis vi f.eks. får inn en nykatt som også heter Luna, vil vi ikke kunne bruke name lengre.*/-- 4.4 - Kontroller antall og plasseringselect count(*) as area_countfrom areas;select count(*) as animal_countfrom animals;select idfrom areaswhere name = 'Quiet Zone';-- Ingen dyr her. Modellen tillater altså en tom avdeling.select count(*)from animalswhere area_id = 4;select idfrom areaswhere name = 'Small Animals';select id, name, speciesfrom animalswhere area_id = 3;-- OPPGAVE 5 - Prøv reglene i databasen-- Her er det bare å klippe og lime inn og se at de feiler.-- OPPGAVE 6 - Endre tabellstrukturen-- 6.1 - Legg til en statusalter table animals add column    status varchar(20) not null default 'new';-- Sjekker etter kjøringselect *from animals;-- Legger inn datainsert into animals (name, species, area_id) values('Nova', 'cat', 1);-- Sjekker etter kjøringselect id, name, weight, admitted_on, statusfrom animalswhere name = 'Nova';/*Mrk: Hvis dere kjørte oppgave 5, så ser dere sannsynligvis atNova fikk id 8 og ikke 7. 5.3 "brukte opp" en auto_inkrement.*/-- 6.2 - Endre standardverdienalter table animals    modify column status varchar(20) not null default 'available';insert into animals (name, species, area_id) values('Oreo', 'cat', 1);-- Sjekker etter kjøringselect id, name, statusfrom animalswhere name in ('Nova', 'Oreo');/*Vi ser at standardverdien er endret, men at den ikke oppdaterereksisterende verdier. default brukes bare når en ny rad settesinn uten verdi.*/-- 6.3 - Gi navnefeltet mer plassalter table animals modify column name varchar(60) not null;show create table animals;/*'alter table' endrer strukturen fra nå'update' endrer data i én eller flere bestemte rader. Strukturenforblir den samme.*/-- 6.4 - Fjern en kolonne og en tabell-- Oppretter en ny tabellcreate table if not exists scratch_labels (    id          int         primary key auto_increment,    label       varchar(40));-- Legger data inn i den nye tabelleninsert into scratch_labels (label) values('Temporary label');-- Ser den nye tabellen med verdiselect *from scratch_labels;-- Fjerner kolonnen labelalter table scratch_labels drop column label;-- Ser at kolonnen er borteselect *from scratch_labels;-- Fjerner hele tabellendrop table scratch_labels;-- Select vil nå si at scratch_labels doesn't exist/*Mrk: id-ene i kommentarene under forutsetter at oppgave 5 er kjørt, slik atNova fikk id 8 og Oreo id 9. Er oppgave 5 ikke kjørt, er de 7 og 8.Sjekk alltid id-en med select før update og delete!*/-- Kontrollpunkt etter oppgave 6select count(*) as animal_countfrom animals;-- Skal være 8select count(*) as area_countfrom areas;-- Skal være 4/*'drop column' fjerner én kolonne og verdiene i den. Tabellen og radenefinnes fortsatt (vi så at id = 1 var igjen).'drop table' fjerner hele tabellen: struktur, regler og alle rader.Ingen av dem kan angres!*/-- OPPGAVE 7 - Oppdater bestemte rader-- 7.1 - To dyr med samme navn-- Finner katten Luna førstselect id, name, species, weightfrom animalswhere name = 'Luna' and species = 'cat';-- id 1update animals set weight = 3.90where id = 1;-- Sjekker etter kjøringselect id, name, species, weightfrom animalswhere name = 'Luna';/*Bare katten har fått ny vekt, kaninen har fortsatt 2.10.Med bare where name = 'Luna' hadde begge fått vekten 3.90. Setningen ergyldig SQL, så vi får ingen feilmelding. Vi får bare feil data.*/-- 7.2 - To endringer i én setningselect *from animalswhere name = 'Rex';-- id 3update animals set name = 'Rex Jr', weight = 19.20where id = 3;-- Sjekker etter kjøringselect *from animalswhere id = 3;-- Navn og vekt er endret. Art, dato, avdeling og status er som før.-- 7.3 - Flytt et dyrselect id, name, species, area_idfrom animalswhere name = 'Luna' and species = 'rabbit';-- id 6select id, namefrom areaswhere name = 'Quiet Zone';-- id 4update animals set area_id = 4where id = 6;-- Sjekker etter kjøringselect id, name, area_idfrom animalswhere id = 6;-- area_id er nå 4select id, name, area_idfrom animalswhere name = 'Pip';-- Pip er fortsatt i Small Animals (area_id 3)/*Det er area_id i dyrets rad som bestemmer hvilken avdeling dyret er i.Endrer vi areas.name, gir vi hele avdelingen nytt navn, og Pip ville"flyttet" med. Vi skal bare flytte ett dyr, så vi endrer fremmednøkkelen.*/-- 7.4 - En kjent verdi blir ukjent igjenselect id, name, weightfrom animalswhere name = 'Nala';-- id 4update animals set weight = 14.60where id = 4;-- Sjekker etter kjøringselect id, name, weightfrom animalswhere id = 4;-- Registreringen var feil, vekten er ikke kjent ennåupdate animals set weight = nullwhere id = 4;-- Sjekker etter kjøringselect id, name, weightfrom animalswhere weight is null;/*Mrk: Denne gir tre rader (Nala, Nova og Oreo), fordi Nova og Oreo hellerikke har vekt. Vil vi bare se Nala: where id = 4 and weight is null.NULL betyr "vi vet ikke". 0 betyr "veier 0 kg", og det er feil.where weight = null gir aldri treff. En sammenligning med NULL blirverken sann eller usann, men ukjent, og da tar where ikke med raden.Bruk alltid is null / is not null.*//*Trygg avgrensningEn update uten where endrer ALLE radene i tabellen.update animals set weight = 3.90; ville gitt alle dyrene samme vekt,og det kan ikke angres. Safe update mode stopper update/delete som ikkeavgrenser med en nøkkelkolonne. Derfor bruker vi id i where.*/-- OPPGAVE 8 - Slett data i riktig rekkefølge-- 8.1 - Fjern én testregistreringselect id, namefrom animalswhere name = 'Oreo';-- id 9 (8 hvis oppgave 5 ikke er kjørt)delete from animalswhere id = 9;-- Sjekker etter kjøringselect id, namefrom animalswhere name in ('Oreo', 'Nova');-- Bare Nova er igjenselect count(*) as animal_countfrom animals;-- 7 dyr-- 8.2 - En avdeling er fortsatt i brukselect idfrom areaswhere name = 'Small Animals';-- id 3-- Denne skal feiledelete from areaswhere id = 3;-- Error 1451: Cannot delete or update a parent row: a foreign key constraint fails/*Vi prøver å slette en foreldrerad (avdelingen), men Pip (barnerad) pekerfortsatt på den. Sletter vi avdelingen, peker Pip på en avdeling som ikkefinnes. Vi har ikke on delete cascade, så databasen nekter.Riktig rekkefølge: flytt (eller slett) barna først, så forelderen.*/select id, name, area_idfrom animalswhere name = 'Pip';-- id 5select idfrom areaswhere name = 'Quiet Zone';-- id 4update animals set area_id = 4where id = 5;-- Sjekker at ingen dyr er igjen i Small Animalsselect id, namefrom animalswhere area_id = 3;-- Tomt resultat-- Nå går detdelete from areaswhere id = 3;-- 8.3 - Kontroller sluttresultatetselect count(*) as animal_countfrom animals;-- 7select count(*) as area_countfrom areas;-- 3select id, name, species, area_idfrom animalswhere area_id = 4;-- Pip og Luna, to kaniner/*delete fjerner rader (data). Tabellen og strukturen blir stående, ogsåom den blir tom.drop table fjerner hele tabellen med alle sju dyrene. Vi skulle barefjerne Oreo, altså én rad, så det er delete vi skal bruke.*/-- OPPGAVE 9 - Les en modell som allerede finnesuse world;/*9.1 - Primærnøkler med andre navncountry:            primary key (Code)countrylanguage:    primary key (CountryCode, Language) <- sammensattcountrylanguage har en sammensatt primærnøkkel. Språket alene er ikke nok,fordi samme språk snakkes i mange land (English finnes for GBR, USA, NORosv.). Det er kombinasjonen land + språk som er unik.*/-- 9.2 - Undersøk språkopplysningerselect CountryCode, Language, Percentagefrom countrylanguagewhere CountryCode = 'NOR';-- Sjekker landkodenselect Code, Namefrom countrywhere Code = 'NOR';/*Et land kan ha mange språk. CountryCode er en fremmednøkkel tilcountry.Code og står på many-siden. Det er samme mønster som at mange dyrhar samme area_id: én forelder (land / avdeling), mange barn(språkrader / dyr).*/use animal_shelter_practice;-- OPPGAVE 10 - Les og rett SQL/*10.1 - Komma og parenteserFeil 1: Det mangler komma etter label varchar(30) not null.Feil 2: Det står et komma for mye etter primary key (id), rett før ).Komma skal skille hver definisjon (kolonne eller regel), men det skal ikkestå komma etter den siste.*/create table if not exists scratch_tags (    id          int             auto_increment,    label       varchar(30)     not null,    primary key (id));drop table scratch_tags;/*10.2 - Kolonner og verdierKolonnelisten har tre kolonner, men values har bare to verdier.Verdien for area_id mangler (Error 1136: Column count doesn't matchvalue count).*/select id, namefrom areaswhere name = 'Cat Wing';-- id 1insert into animals (name, species, area_id) values('Tyra', 'cat', 1);/*10.3 - Gyldig SQL med feil utvalgwhere name = 'Luna' treffer både katten og kaninen, og begge får vekten2.50. Det er ingen syntaksfeil, så setningen kjører. Det er utvalget somer feil.*/select id, name, species, weightfrom animalswhere name = 'Luna' and species = 'rabbit';-- id 6update animals set weight = 2.50where id = 6;-- Sjekker etter kjøringselect id, name, species, weightfrom animalswhere id = 6;/*10.4 - Sletting er ikke en selectdelete * er syntaksfeil. delete sletter hele rader, så vi velger ikkekolonner. Riktig form er delete from tabell where ...Mrk: Nova skal bli i databasen, så delete under er kommentert ut.*/select id, name, speciesfrom animalswhere name = 'Nova';-- id 8 (7 hvis oppgave 5 ikke er kjørt)-- delete from animals-- where id = 8;-- EKSTRA UTFORDRINGER-- Mrk: Tallene under gjelder hvis 10.2 og 10.3 er kjørt (Tyra finnes)./*Utfordring 1 - Frivillige og dyr[volunteers]-||---O<[volunteers_animals]>O---||-[animals]volunteers:             id (PK), namevolunteers_animals:     id (PK), volunteer_id (FK), animal_id (FK)Mange-til-mange løses med en koblingstabell og to én-til-mange-forhold.Paret (volunteer_id, animal_id) skal være unikt, slik at samme frivilligikke kobles til samme dyr to ganger.Hver fremmednøkkel alene skal IKKE være unique. Da kunne en frivillig barefulgt opp ett dyr (og et dyr bare hatt én frivillig), og da er det ikkelenger mange-til-mange.*/-- Utfordring 2 - Bygg og prøv koblingstabellencreate table if not exists volunteers (    id          int             primary key auto_increment,    name        varchar(60)     not null);create table if not exists volunteers_animals (    id              int     primary key auto_increment,    volunteer_id    int     not null,    animal_id       int     not null,    unique (volunteer_id, animal_id),    foreign key (volunteer_id)  references volunteers(id),    foreign key (animal_id)     references animals(id));insert into volunteers (name) values('Emma Hansen'),('Oliver Berg'),('Sophie Lund');-- Henter id-ene før vi lager koblingerselect id, namefrom volunteers;-- 1 Emma, 2 Oliver, 3 Sophieselect id, name, speciesfrom animalsorder by id;-- 1 Luna (cat), 3 Rex Jr, 4 Nala, 5 Pip, 8 Nova ...insert into volunteers_animals (volunteer_id, animal_id) values(1, 1),     -- Emma: Luna (cat)(1, 3),     -- Emma: Rex Jr(2, 1),     -- Oliver: Luna (cat)  <- Luna har to frivillige(2, 5),     -- Oliver: Pip(3, 4),     -- Sophie: Nala(3, 8);     -- Sophie: Nova (bruk Novas id fra select over)-- Denne skal feileinsert into volunteers_animals (volunteer_id, animal_id) values(1, 1);-- Error 1062: Duplicate entry '1-1'. unique (volunteer_id, animal_id) stopper den.-- Sletter én koblingselect idfrom volunteers_animalswhere volunteer_id = 2 and animal_id = 5;-- id 4delete from volunteers_animalswhere id = 4;-- Sjekker at både den frivillige og dyret fortsatt finnesselect id, namefrom volunteerswhere id = 2;select id, namefrom animalswhere id = 5;/*Vi sletter bare koblingen. Oliver og Pip er egne rader i egne tabellerog blir ikke berørt.*//*Utfordring 3 - Høyst én profil per frivillig[volunteers]-||---------O|-[volunteer_profiles]Tilhører nøyaktig 1       har 0..1 profilforeign key:    profilen må høre til en frivillig som finnesnot null:       en profil kan ikke finnes uten frivilligunique:         samme volunteer_id kan bare stå én gang, altså høyst én                profil per frivilligEn frivillig uten profil er lov, fordi det bare er profiltabellen sompeker på volunteers. Ingenting krever at det finnes en profilrad.Telefonnummer er tekst: vi regner ikke på det, og det kan ha +, mellomromog ledende nuller.*/create table if not exists volunteer_profiles (    id              int             primary key auto_increment,    volunteer_id    int             not null unique,    phone           varchar(20),    bio             varchar(255),    foreign key (volunteer_id)  references volunteers(id));insert into volunteer_profiles (volunteer_id, phone, bio) values(1, '+47 912 34 567', 'Loves cats and weekend shifts.');-- Denne skal feileinsert into volunteer_profiles (volunteer_id, phone, bio) values(1, '+47 400 00 000', 'Second profile');-- Error 1062: Duplicate entry '1' for key volunteer_id-- Utfordring 4 - NULL og tom tekstcreate table if not exists scratch_names (    id          int             primary key auto_increment,    nickname    varchar(40)     not null);-- Denne gårinsert into scratch_names (nickname) values('');-- Denne skal feileinsert into scratch_names (nickname) values(null);-- Error 1048: Column 'nickname' cannot be nullselect id, nicknamefrom scratch_nameswhere nickname = '';/*'' er en verdi (tekst med lengde 0), ikke NULL. not null stopper derforbare NULL. Skal vi kreve et ordentlig navn, trenger vi en ekstra regel,f.eks. check (trim(nickname) <> '') (MySQL 8.0.16 og nyere), ellerkontroll i applikasjonen.*/drop table scratch_names;/*Utfordring 5 - En ny modell på egen hånd[telescopes]-||--------------O<[observations]Brukes av nøyaktig 1        har 0..mange*/create database if not exists astronomy_practice;use astronomy_practice;select database();create table if not exists telescopes (    id              int                 primary key auto_increment,    name            varchar(60)         not null unique,    diameter_mm     smallint unsigned   not null);create table if not exists observations (    id              int             primary key auto_increment,    observed_on     date            not null,    object_name     varchar(60)     not null,    telescope_id    int             not null,    foreign key (telescope_id)  references telescopes(id));insert into telescopes (name, diameter_mm) values('North Refractor', 102),('Big Dobson', 254);select id, namefrom telescopes;-- 1 North Refractor, 2 Big Dobsoninsert into observations (observed_on, object_name, telescope_id) values('2026-10-02', 'Moon', 1),('2026-10-02', 'Jupiter', 1),('2026-10-15', 'Andromeda Galaxy', 2),('2026-10-21', 'Orion Nebula', 2);-- Retter datoen på én observasjonselect id, observed_on, object_namefrom observationswhere object_name = 'Jupiter';-- id 2update observations set observed_on = '2026-10-03'where id = 2;-- Denne skal feiledelete from telescopeswhere id = 1;-- Error 1451: To observasjoner peker fortsatt på teleskopet (ingen cascade).-- Oversiktselect id, name, diameter_mmfrom telescopes;select id, observed_on, object_name, telescope_idfrom observationsorder by observed_on;use animal_shelter_practice;/*Utfordring 6 - Forklar og kontroller eget arbeidFremmednøkkel: foreign key (area_id) references areas(id)    Gjør:       Krever at hvert dyr peker på en avdeling som finnes.    Kontroll:   Prøv insert med en area_id som ikke finnes -> Error 1452.    Mulig feil: Ulik datatype, eller areas opprettet etter animals.Strukturendring: alter table animals modify column status ... default 'available'    Gjør:       Endrer standardverdien for nye rader.    Kontroll:   insert uten status, deretter select status.    Mulig feil: Glemme not null, så kolonnen plutselig tillater NULL.Dataendring: update animals set weight = 3.90 where id = 1    Gjør:       Endrer vekten på ett bestemt dyr.    Kontroll:   select før og etter, på begge Luna.    Mulig feil: where name = 'Luna' treffer to dyr.Kjørerekkefølge:1. 01_schema.sql      Opprettelse (create database / create table)2. 02_data.sql        Startdata (insert)3. 03_changes.sql     Senere endringer (alter / update / delete)4. 04_checks.sql      Kontroller (select) og forsøk som SKAL feile5. 05_challenges.sql  Valgfrittinsert, alter, update og delete endrer tilstanden. Kjører vi dem to ganger,får vi doble rader, feil ved add column, eller id-er som ikke stemmerlenger. Filene er en logg, ikke et skript vi kjører blindt fra toppen.*//*GIT TIL SLUTTgit add 07-sql-modeling-crud/02-exercisesgit commit -m "Added modeling and CRUD exercises"git push*/